import test from "node:test";import assert from "node:assert/strict";import {createStore} from "./orders.mjs";
test("duplicate and concurrent order requests share one durable result",async()=>{const store=createStore();const results=await Promise.all(Array.from({length:12},()=>store.create("key",{item:"book"})));assert.equal(new Set(results.map(r=>r.id)).size,1);assert.equal(store.count(),1);assert.equal((await store.create("key",{item:"book"})).id,results[0].id);});
test("different keys create different orders; failed creation is retryable",async()=>{let attempt=0;const store=createStore(async()=>{if(attempt++===0)throw new Error("storage");});await assert.rejects(store.create("a",{}));const a=await store.create("a",{}),b=await store.create("b",{});assert.notEqual(a.id,b.id);assert.equal(store.count(),2);});
